 "content": "def transform(grid):
    # Color enclosed zero pockets; small pockets receive 7, broad ones 8.
    # Exterior zeros are identified by flood fill from the grid boundary.
    from collections import deque
    h, w = len(grid), len(grid[0])
    seen = set()
    q = deque()
    for r in range(h):
        for c in range(w):
            if (r in (0, h-1) or c in (0, w-1)) and grid[r][c] == 0:
                seen.add((r,c)); q.append((r,c))
    while q:
        r,c=q.popleft()
        for rr,cc in ((r-1,c),(r+1,c),(r,c-1),(r,c+1)):
            if 0<=rr<h and 0<=cc<w and grid[rr][cc]==0 and (rr,cc) not in seen:
                seen.add((rr,cc));q.append((rr,cc))
    out=[row[:] for row in grid]
    # The demos encode two colors by the area of the closed cavity.
    remaining={(r,c) for r in range(h) for c in range(w) if grid[r][c]==0 and (r,c) not in seen}
    comps=[]
    while remaining:
        start=remaining.pop(); comp={start}; stack=[start]
        while stack:
            r,c=stack.pop()
            for p in ((r-1,c),(r+1,c),(r,c-1),(r,c+1)):
                if p in remaining: remaining.remove(p);comp.add(p);stack.append(p)
        comps.append(comp)
    for comp in comps:
        color=7 if len(comp)<=2 else 8
        for r,c in comp: out[r][c]=color
    return out
